import "server-only";
import { getCloudflareContext } from "@opennextjs/cloudflare";

/**
 * Cloudflare resources bound to the Worker in wrangler.jsonc (types generated by `npm run cf-types`):
 * DB (D1), MEDIA (R2), PROCESSOR (media processor container; absent in dev and tests, which use
 * PROCESSOR_URL) and GRAB_LIMITER (shared rate limiter; absent locally).
 */
export function bindings(): CloudflareEnv {
  return getCloudflareContext().env;
}

/**
 * A text setting from wrangler.jsonc `vars` or `wrangler secret`. The deployed Worker exposes these
 * on process.env; `next dev` only has them on the Cloudflare context, so check both.
 */
export function setting(name: string): string | undefined {
  const fromProcess = process.env[name];
  if (fromProcess !== undefined) return fromProcess;
  try {
    const value = (getCloudflareContext().env as unknown as Record<string, unknown>)[name];
    return typeof value === "string" ? value : undefined;
  } catch {
    return undefined; // outside a request (e.g. unit tests)
  }
}
